const body = $input.item.json.body || {};
const tipo = body.tipo || 'OTP';
const codigo = body.datos?.codigo || '';
const nombre = body.destinatario?.nombre || 'Usuario';
const asunto = body.datos?.asunto || 'Notificación RompGPS';

let htmlContent = '';
if (tipo === 'RECUPERAR_PASSWORD') {
  htmlContent = `
    <div style="background-color:#0b0f14; color:#ffffff; padding:30px; font-family:Arial,sans-serif; border-radius:12px; max-width:500px; margin:auto; border:1px solid #10b981;">
      <h2 style="color:#10b981; margin-top:0;">Recuperación de Contraseña - RompGPS</h2>
      <p>Hola <strong>${nombre}</strong>,</p>
      <p>Recibimos una solicitud para restablecer tu contraseña. Tu código de seguridad temporal es:</p>
      <div style="background-color:#161f28; font-size:32px; font-weight:bold; letter-spacing:8px; text-align:center; padding:18px; border-radius:8px; color:#10b981; margin:20px 0;">
        ${codigo}
      </div>
      <p style="font-size:13px; color:#9ca3af;">Este código expira en 10 minutos. Si tú no solicitaste este cambio, ignora este mensaje.</p>
    </div>`;
} else {
  htmlContent = `
    <div style="background-color:#0b0f14; color:#ffffff; padding:30px; font-family:Arial,sans-serif; border-radius:12px; max-width:500px; margin:auto; border:1px solid #10b981;">
      <h2 style="color:#10b981; margin-top:0;">Código de Acceso 2FA - RompGPS</h2>
      <p>Hola <strong>${nombre}</strong>,</p>
      <p>Tu código de verificación de dos factores para iniciar sesión es:</p>
      <div style="background-color:#161f28; font-size:32px; font-weight:bold; letter-spacing:8px; text-align:center; padding:18px; border-radius:8px; color:#10b981; margin:20px 0;">
        ${codigo}
      </div>
      <p style="font-size:13px; color:#9ca3af;">Válido durante 5 minutos. No lo compartas con nadie.</p>
    </div>`;
}

return {
  json: {
    toEmail: body.destinatario?.correo,
    subject: asunto,
    html: htmlContent
  }
};

const body = $input.item.json.body || {};
const tipo = body.tipo;
const datos = body.datos || {};
const placa = datos.vehiculoPlaca || 'Vehículo';

let texto = '';
if (tipo === 'ALERTA_MOVIMIENTO') {
  texto = `🚨 *ALERTA DE SEGURIDAD ROMPGPS*\n\nTu vehículo *[Placa: ${placa}]* registró movimiento no autorizado con el motor apagado.\n\n📍 Ingresa de inmediato a la plataforma para rastrear su posición en vivo.`;
} else if (tipo === 'CORTE_MOTOR') {
  texto = `⚡ *CORTE DE MOTOR CONFIRMADO*\n\nEl corte de motor ha sido ejecutado con éxito en el vehículo *[Placa: ${placa}]*. El relé de encendido ha sido inmovilizado.`;
} else if (tipo === 'MANTENIMIENTO_PREDICTIVO') {
  texto = `🔧 *MANTENIMIENTO PREDICTIVO ROMPGPS*\n\nHola, tu vehículo *[Placa: ${placa}]* ha acumulado *${datos.kilometrosActuales || 0} km*.\nSegún el modelo de desgaste, te restan aproximadamente *${(datos.kilometrosMantenimiento || 5000) - (datos.kilometrosActuales || 0)} km* para el mantenimiento recomendado.`;
} else {
  texto = `🔐 *RompGPS 2FA*\n\nTu código de verificación es: *${datos.codigo}* (Válido por 5 minutos).`;
}

return {
  json: {
    toPhone: body.destinatario?.telefono,
    message: texto
  }
};
